r=os.path.dirname(os.path.dirname(os.path.abspath(__file__)));a=sys.argv[sys.argv.index('--')+1:];mode=a[0];samples=int(a[1]);p=r+'/models/'+mode+'.blend';sha=hashlib.sha256(open(p,'rb').read()).hexdigest();bpy.ops.wm.open_mainfile(filepath=p);s=bpy.context.scene;s.cycles.samples=samples;s.cycles.use_denoising=False;s.render.resolution_x=1192;s.render.resolution_y=671;s.render.resolution_percentage=100;s.render.threads_mode='FIXED';s.render.threads=6;out=[]
